/**
 * Generates `src/spec/sections.ts` from spec.md.
 *
 *   npx tsx scripts/spec/sections.ts [--check]
 *
 * The generated file is committed. That keeps the build free of an ordering
 * dependency, and confines the diff of a renumber to one file — which is the
 * whole point of making the numbers a derived value.
 *
 * No line numbers are emitted: moving a heading must produce no diff here, or
 * the registry would churn on every edit to the prose.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { parseSpec, REPO_ROOT } from "./parse.js";

const OUT_PATH = join(REPO_ROOT, "src", "spec", "sections.ts");

const HEADER = `// GENERATED by \`npm run spec:sections\` from spec.md. Do not edit.
//
// A section's slug is its identity; its number is where it happens to sit
// today. Cite a section by slug and a renumber cannot reach the citation.

export interface SpecSection {
  readonly slug: string;
  /** \`"7.8"\`. Null for the title and the unnumbered \`####\` headings. */
  readonly number: string | null;
  readonly title: string;
  readonly level: 1 | 2 | 3 | 4;
}
`;

const FOOTER = `
/** Every heading in spec.md. */
export type SpecSlug = keyof typeof SPEC_SECTIONS;

/**
 * The headings that carry a number, and so are the ones a diagnostic or a
 * comment may cite. Because this is a union of literals, a citation that names
 * a section spec.md does not have fails to compile.
 */
export type SpecId = {
  [K in SpecSlug]: (typeof SPEC_SECTIONS)[K]["number"] extends string ? K : never;
}[SpecSlug];
`;

function generate(): string {
  const doc = parseSpec();
  const rows = doc.headings.map((h) => {
    const number = h.number === null ? "null" : JSON.stringify(h.number);
    return (
      `  ${JSON.stringify(h.slug)}: { slug: ${JSON.stringify(h.slug)}, ` +
      `number: ${number}, title: ${JSON.stringify(h.title)}, level: ${h.level} },`
    );
  });
  return `${HEADER}
export const SPEC_SECTIONS = {
${rows.join("\n")}
} as const satisfies Record<string, SpecSection>;
${FOOTER}`;
}

function main(argv: readonly string[]): number {
  const wanted = generate();
  const current = (() => {
    try {
      return readFileSync(OUT_PATH, "utf8");
    } catch {
      return null;
    }
  })();

  if (current === wanted) {
    console.log("src/spec/sections.ts: up to date");
    return 0;
  }
  if (argv.includes("--check")) {
    console.error(
      "src/spec/sections.ts is out of date with spec.md — run `npm run spec:sections`",
    );
    return 1;
  }
  writeFileSync(OUT_PATH, wanted, "utf8");
  console.log(`src/spec/sections.ts: wrote ${wanted.split("\n").length} lines`);
  return 0;
}

process.exit(main(process.argv.slice(2)));
